-- Identity set, 0010: the transactional outbox (outbox plan Task 5; "Outbox table"). Generated by
-- drizzle-kit, then hand-edited into the plan's order: CREATE -> distribution -> indexes -> RLS ->
-- grants -> policy. One statement each: with local execution off, Citus builds the shards over new
-- connections, so each statement commits before the next. Distributed by tenant_id and colocated with
-- app.tenant_colocation; no FK. The runtime role is insert-only (no SELECT grant: it never reads the
-- table, so its inserts carry no RETURNING) and may insert only its own tenant's rows; app_system
-- (BYPASSRLS) polls, marks and purges through identity's pinned outbox.* system methods.
CREATE TABLE "identity"."outbox" (
	"tenant_id" uuid NOT NULL,
	"id" uuid NOT NULL,
	"topic" text NOT NULL,
	"key" text,
	"envelope" jsonb NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"published_at" timestamp (3) with time zone,
	CONSTRAINT "outbox_tenant_id_id_pk" PRIMARY KEY("tenant_id","id")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('identity.outbox');--> statement-breakpoint
CREATE INDEX "outbox_unpublished_idx" ON "identity"."outbox" USING btree ("created_at","id") WHERE "identity"."outbox"."published_at" IS NULL;--> statement-breakpoint
CREATE INDEX "outbox_published_at_idx" ON "identity"."outbox" USING btree ("published_at") WHERE "identity"."outbox"."published_at" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "identity"."outbox" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "identity"."outbox" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
GRANT INSERT ON "identity"."outbox" TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "identity"."outbox" TO app_system;--> statement-breakpoint
CREATE POLICY "outbox_insert" ON "identity"."outbox" FOR INSERT TO app_runtime WITH CHECK (tenant_id = app.tenant_id());
